import React, { Component } from 'react'
import { connect } from 'react-redux'
import ProfileStyleWrapper, { ProfileDetailContainer, ProfileHeader } from './index.style'
import moment from 'moment'
import {
  Form,
  Input,
  Icon,
  DatePicker,
  Radio,
  Select,
  Upload,
  notification
} from 'antd'
import { injectIntl } from 'react-intl'
import _ from 'lodash/object'
import PropTypes from 'prop-types'
import userActions from '../../redux/user/actions'
import IntlMessages from '../../components/utility/intlMessages'
import OtpFormPhone from './otpFormPhone'
import OtpFormEmail from './otpFormEmail'
import { belongsToAnotherVertical } from '../../helpers/agencyUtils'
import { CALENDAR, EMAIL, LOCATION, PHONE, PROFILE, WEBSITE } from '../../constants/icons'
import DetailAttribute from '../../components/DetailAttribute/DetailAttribute'
import BankAccounts from '../Documents/components/BankAccounts'
import ProfileModal from '../Documents/components/ProfileModal/profileModal'
import { LANG_STRINGS } from '../../constants/lang'

const FormItem = Form.Item
const RadioGroup = Radio.Group
const Option = Select.Option

const {
  getUserDetails,
  getLocations,
  uploadUserFile,
  updateUser,
  updateUserProfile,
  updateCompleteUser,
  resetUserRedux
} = userActions

class Profile extends Component {
  state = {
    editProfileModalVisible: false,
    showSuccessModal: false,
    showErrorModal: false,
    showAvatarUploadModal: false,
    modalSuccessErrorTitle: ''
  }

  componentDidMount () {
    this.props.getUserDetails()
    this.props.getLocations()
  }

  componentDidUpdate (prevProps) {
    if (prevProps.details !== this.props.details) {
      const multiVerticalCustomer = belongsToAnotherVertical(this.props.details)
      this.setState({ multiVerticalCustomer })
    }
  }

  componentWillReceiveProps (nextProps) {
    const {
      userDetailsLoading,
      userDetailsError,
      getUserDetailsMessage,
      locationsLoading,
      locationsError,
      getLocationsMessage,
      uploadFileLoading,
      uploadFileError,
      uploadUserFileMessage,
      updateCompleteUserLoading,
      updateCompleteUserError,
      updateCompleteUserMessage
    } = nextProps

    if (!userDetailsLoading && !!userDetailsError && getUserDetailsMessage) {
      notification.error({
        key: 'profile',
        message: this.intlText({ id: getUserDetailsMessage })
      })
      this.props.resetUserRedux(['getUserDetailsMessage'])
    }

    if (!locationsLoading && !!locationsError && getLocationsMessage) {
      notification.error({
        key: 'profile',
        message: this.intlText({ id: getLocationsMessage })
      })
      this.props.resetUserRedux(['getLocationsMessage'])
    }

    if (!uploadFileLoading && uploadUserFileMessage) {
      notification[uploadFileError ? 'error' : 'success']({
        key: 'profile',
        message: this.intlText({ id: uploadUserFileMessage })
      })
      this.props.resetUserRedux(['uploadUserFileMessage'])
    }

    if (!updateCompleteUserLoading && updateCompleteUserMessage) {
      this.setState({ editProfileModalVisible: false })
      updateCompleteUserError ? this.setState({ showErrorModal: true }) : this.setState({ showSuccessModal: true })

      this.props.resetUserRedux(['updateCompleteUserMessage'])
    }
  }

  showEditProfileModal = () => {
    this.setState({ editProfileModalVisible: true })
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields(['name', 'dob', 'gender', 'location', 'email', 'phone'], (err, values) => {
      if (!err) {
        let payload = Object.keys(values).reduce((result, key) => {
          let value = values[key]
          if (value) {
            if (key === 'dob') {
              result[key] = moment(value).format('YYYY-MM-DD')
            } else if (key !== 'email') {
              result[key] = value
            }
          }
          return result
        }, {})
        this.setState({ modalSuccessErrorTitle: this.intlText({ id: LANG_STRINGS.editProfile }) })
        this.props.updateCompleteUser({ body: payload })
      }
    })
  };

  handleAvatarSubmit = e => {
    e.preventDefault()
    const { userFile } = this.props

    const updatedAvatar = _.get(userFile, 'url')
    const payload = {}

    if (updatedAvatar) {
      Object.assign(payload, { profile_picture_url: updatedAvatar })
    }

    this.setState({ showAvatarUploadModal: false, modalSuccessErrorTitle: this.intlText({ id: LANG_STRINGS.changePicture }) })
    this.props.updateCompleteUser({ body: payload })
  };

  customRequest = ({ file, onSuccess, onError }) => {
    const { type } = file
    const validImageTypes = ['image/gif', 'image/jpeg', 'image/png']

    if (validImageTypes.includes(type)) {
      const formData = new FormData()
      formData.append('file', file)

      // Start upload
      this.props.uploadUserFile({
        body: formData,
        onSuccess: (response) => {
          // Call success callback
          onSuccess(response)
          this.setState({ showSuccessModal: true })
        },
        onError: (error) => {
          // Call error callback
          onError(error)
          this.setState({ showErrorModal: true })
        }
      })
    } else {
      notification.error({
        key: 'profile',
        message: this.intlText({ id: 'Salah format, harap unggah hanya gif/jpeg/png' })
      })
    }
  };

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  compareValue = (key, e, value) => {
    /*
      check is current values are same as input
    */
    const {
      form: { validateFields }
    } = this.props
    validateFields([key], (errors, values) => {
      this.setState({
        [`touched_${key}`]: e.target.value !== value,
        [`success_${key}`]: false,
        [key]: e.target.value
      })
    })
  }

  updateSuccess = (key) => {
    /*
      passed as props then called by otp form component once successfully updated phone/email
    */
    this.setState({
      [`touched_${key}`]: false,
      [`success_${key}`]: true
    })
  }

  resetFields = () => {
    this.props.form.resetFields()
    this.props.resetUserRedux(['userFile'])
    this.setState({
      touched_phone: false,
      touched_email: false
    }, () => this.back())
  }

  back = () => {
    const { history } = this.props
    if (history) {
      const { action } = history
      if (action === 'POP') {
        history.push('/')
      } else {
        history.goBack()
      }
    }
  };

  render () {
    const {
      form,
      details,
      locations,
      userFile,
      locationsLoading
    } = this.props
    const { getFieldDecorator, getFieldError } = form
    const {
      touched_phone: touchedPhone,
      success_phone: successPhone,
      touched_email: touchedEmail,
      success_email: successEmail,
      phone,
      email,
      multiVerticalCustomer
    } = this.state
    const getCurrentLocation = () => {
      try {
        const currentLocation = locations[Number(_.get(details, 'profile.location')) - 1]
        return currentLocation || {}
      } catch (error) {
        console.error(error)
        return {}
      }
    }
    return (
      <React.Fragment>
        <ProfileStyleWrapper>
          <ProfileHeader>
            <div className='profile-header'>
              <div className='profile-header-content'>
                <div className='logo-box'>
                  <img src={PROFILE} />
                </div>
                <IntlMessages id='Profil Saya' />
              </div>
            </div>
          </ProfileHeader>
          <ProfileDetailContainer>
            <ProfileModal isOpen={this.state.editProfileModalVisible} title={this.intlText({ id: LANG_STRINGS.editProfile })}>
              <Form onSubmit={this.handleSubmit}>
                <div className='modal-body-content'>
                  <FormItem label={this.intlText({ id: 'Nama' })}>
                    {getFieldDecorator('name', {
                      rules: [{ required: true, message: this.intlText({ id: 'Nama harus diisi' }) }],
                      initialValue: _.get(details, 'name')
                    })(
                      <Input
                        disabled={multiVerticalCustomer}
                        placeholder={this.intlText({ id: 'Nama' })}
                      />
                    )}
                  </FormItem>
                  <FormItem label={this.intlText({ id: 'Jenis Kelamin' })}>
                    {getFieldDecorator('gender', {
                      initialValue: _.get(details, 'profile.gender')
                    })(
                      <RadioGroup>
                        <Radio
                          key={1}
                          value={'male'}
                          disabled={multiVerticalCustomer}
                        >
                          <IntlMessages id='Pria' />
                        </Radio>
                        <Radio
                          key={2}
                          value={'female'}
                          disabled={multiVerticalCustomer}
                        >
                          <IntlMessages id='Wanita' />
                        </Radio>
                      </RadioGroup>
                    )}
                  </FormItem>
                  <FormItem label={this.intlText({ id: 'Tanggal Lahir' })}>
                    {getFieldDecorator('dob', {
                      initialValue: _.get(details, 'profile.dob') ? moment(_.get(details, 'profile.dob'), 'YYYY-MM-DD') : null
                    })(
                      <DatePicker
                        disabled={multiVerticalCustomer}
                        format={'DD-MM-YYYY'}
                        placeholder={this.intlText({ id: 'Pilih tanggal' })}
                        disabledDate={value => value > moment()}
                      // disable selection above today
                      />
                    )}
                  </FormItem>
                  <FormItem label={this.intlText({ id: 'Lokasi' })}>
                    {getFieldDecorator('location', {
                      initialValue: Number(_.get(details, 'profile.location')) || undefined
                    })(
                      <Select
                        showSearch
                        loading={!!locationsLoading}
                        disabled={!!locationsLoading || multiVerticalCustomer}
                        placeholder={this.intlText({ id: 'Pilih lokasi' })}
                        filterOption={(input, option) =>
                          _.get(option, 'props.children', []).join('').toLowerCase().includes(input.toLowerCase())}
                      >

                        {
                          locations.map(({ id, name, country }) => {
                            return (
                              <Option
                                key={id}
                                value={id}
                              >
                                {name} - {country}
                              </Option>
                            )
                          })
                        }
                      </Select>
                    )}
                  </FormItem>
                  <FormItem label={this.intlText({ id: 'Nomor Telepon' })}>
                    <div className={touchedPhone && !getFieldError('phone') ? 'input-wrapper' : ''}>
                      {getFieldDecorator('phone', {
                        validateFirst: true,
                        rules: [
                          {
                            required: true, message: this.intlText({ id: 'Nomor Telepon harus diisi' })
                          },
                          {
                            pattern: /^\d{2,}.*/,
                            message: this.intlText({ id: 'Minimum kode negara adalah 2 digit' })
                          },
                          {
                            pattern: /^\d*-\d*/,
                            message: this.intlText({ id: 'Format harus sebagai berikut; XX-XXXXXXXXXX' })
                          },
                          {
                            pattern: /^\d{2,3}-.*/,
                            message: this.intlText({ id: 'Maksimum kode negara adalah 3 digit' })
                          },
                          {
                            pattern: /^\d{2,3}-\d{9,12}/,
                            message: this.intlText({ id: 'Panjang nomor telepon harus 9 - 12 digit' })
                          }
                        ],
                        initialValue: _.get(details, 'phone')
                      })(
                        <Input
                          placeholder={this.intlText({ id: 'Nomor Telepon' })}
                          onChange={e => this.compareValue('phone', e, _.get(details, 'phone'))}
                          disabled={multiVerticalCustomer}
                          suffix={
                            <Icon
                              type={successPhone ? 'check-circle' : touchedPhone ? 'warning' : ''}
                              style={{ color: successPhone ? '#23a637' : touchedPhone ? '#f5a623' : '' }}
                            />
                          }
                        />
                      )}
                    </div>
                  </FormItem>
                  {touchedPhone && !getFieldError('phone') && (
                    <OtpFormPhone
                      phone={phone}
                      disabled={multiVerticalCustomer}
                      oldPhone={_.get(details, 'phone')}
                      updateSuccess={this.updateSuccess}
                    />
                  )}
                  <FormItem label={this.intlText({ id: 'Email' })}>
                    <div className={touchedEmail && !getFieldError('email') ? 'input-wrapper' : ''}>
                      {getFieldDecorator('email', {
                        rules: [
                          { required: true, message: this.intlText({ id: 'Email harus diisi' }) },
                          { type: 'email', message: this.intlText({ id: 'Masukkan email yang valid' }) }
                        ],
                        initialValue: _.get(details, 'email')
                      })(
                        <Input
                          placeholder={this.intlText({ id: 'Email' })}
                          onChange={e => this.compareValue('email', e, _.get(details, 'email'))}
                          disabled={multiVerticalCustomer}
                          suffix={
                            <Icon
                              type={successEmail ? 'check-circle' : touchedEmail ? 'warning' : ''}
                              style={{ color: successEmail ? '#23a637' : touchedEmail ? '#f5a623' : '' }}
                            />
                          }
                        />
                      )}
                    </div>
                  </FormItem>
                  {touchedEmail && !getFieldError('email') && (
                    <OtpFormEmail
                      disabled={multiVerticalCustomer}
                      email={email}
                      oldEmail={_.get(details, 'email')}
                      updateSuccess={this.updateSuccess}
                    />
                  )}
                </div>
                <div className='confirmation-container'>
                  <button className='btn-outline-success' onClick={() => this.setState({ editProfileModalVisible: false })}>Batal</button>
                  <button className='btn-success' type='submit'>Simpan</button>
                </div>
              </Form>
            </ProfileModal>
            <ProfileModal isOpen={this.state.showErrorModal}>
              <div className='success-animation'>
                <div className='ui-error'>
                  <svg viewBox='0 0 87 87' version='1.1' xmlns='http://www.w3.org/2000/svg' xmlnsXlink='http://www.w3.org/1999/xlink'>
                    <g id='Page-1' stroke='none' strokeWidth='1' fill='none' fillRule='evenodd'>
                      <g id='Group-2' transform='translate(2.000000, 2.000000)'>
                        <circle id='Oval-2' stroke='rgba(252, 191, 191, .5)' strokeWidth='4' cx='41.5' cy='41.5' r='41.5' />
                        <circle className='ui-error-circle' stroke='#F74444' strokeWidth='4' cx='41.5' cy='41.5' r='41.5' />
                        <path className='ui-error-line1' d='M22.244224,22 L60.4279902,60.1837662' id='Line' stroke='#F74444' strokeWidth='3' strokeLinecap='square' />
                        <path className='ui-error-line2' d='M60.755776,21 L23.244224,59.8443492' id='Line' stroke='#F74444' strokeWidth='3' strokeLinecap='square' />
                      </g>
                    </g>
                  </svg>
                </div>
                <h4 className='modal-title'><this.intlText id={'Error'} /></h4>
                <div className='btn-container'>
                  <button className='btn-success' type='button' onClick={() => this.setState({ showErrorModal: false })}>Tutup</button>
                </div>
              </div>
            </ProfileModal>
            <ProfileModal isOpen={this.state.showSuccessModal} title={this.state.modalSuccessErrorTitle}>
              <div className='success-animation'>
                <svg className='checkmark' xmlns='http://www.w3.org/2000/svg' viewBox='0 0 52 52'><circle className='checkmark__circle' cx='26' cy='26' r='25' fill='none' /><path className='checkmark__check' fill='none' d='M14.1 27.2l7.1 7.2 16.7-16.8' /></svg>
              </div>
              <h4 className='modal-title'><this.intlText id={'Sukses'} /></h4>
              <div className='btn-container'>
                <button className='btn-success' type='button' onClick={() => this.setState({ showSuccessModal: false })}>Tutup</button>
              </div>
            </ProfileModal>
            <ProfileModal isOpen={this.state.showAvatarUploadModal} title={this.intlText({ id: LANG_STRINGS.changePicture })}>
              <Form onSubmit={this.handleAvatarSubmit}>
                <Upload
                  name='avatar'
                  listType='picture-card'
                  className='avatar-uploader'
                  showUploadList={false}
                  multiple={false}
                  disabled={multiVerticalCustomer}
                  customRequest={this.customRequest}
                >
                  {(!_.get(userFile, 'url') && !_.get(details, 'profile.profile_picture_url')) ? (
                    <div className='profile-initials'>
                      {(() => {
                        const name = _.get(details, 'name', '')
                        if (name) {
                          const syllables = name.split(/[\s-]+/)
                          if (syllables.length >= 2) {
                            return <p>{`${syllables[0][0].toUpperCase()}${syllables[1][0].toUpperCase()}`}</p>
                          }
                          return <p>{syllables[0][0].toUpperCase()}</p>
                        }
                        return <p>N/A</p>
                      })()}
                    </div>
                  ) : (
                    <img
                      src={_.get(userFile, 'url') || _.get(details, 'profile.profile_picture_url')}
                      alt='avatar'
                      className='profile-picture'
                    />
                  )}
                </Upload>
                <div className='confirmation-container'>
                  <button className='btn-outline-success' type='button' onClick={() => this.setState({ showAvatarUploadModal: false })}><IntlMessages id='Batal' /></button>
                  <button className='btn-success' type='submit'><IntlMessages id='Simpan' /></button>
                </div>
              </Form>
            </ProfileModal>
            <div className='profile-detail-card'>
              <div className='profile-detail-card-container'>
                <div className='profile-detail-card-header'>
                  <h3><IntlMessages id='Personal Detail' /></h3>
                  <button className='profile-button' onClick={() => this.setState({ editProfileModalVisible: true })}><IntlMessages id='Ubah Data' /></button>
                </div>
                <div className='profile-detail-card-content'>
                  <div className='profile-detail-pict'>
                    {(!_.get(userFile, 'url') && !_.get(details, 'profile.profile_picture_url')) ? (
                      <div className='profile-initials'>
                        {(() => {
                          const name = _.get(details, 'name', '')
                          if (name) {
                            const syllables = name.split(/[\s-]+/)
                            if (syllables.length >= 2) {
                              return <p>{`${syllables[0][0].toUpperCase()}${syllables[1][0].toUpperCase()}`}</p>
                            }
                            return <p>{syllables[0][0].toUpperCase()}</p>
                          }
                          return <p>N/A</p>
                        })()}
                      </div>
                    ) : (
                      <img
                        src={_.get(details, 'profile.profile_picture_url')}
                        alt='avatar'
                        className='profile-picture'
                      />
                    )}
                    <div className='profile-detail-pict-text'>
                      <h4>{_.get(details, 'name', 'Unknown User')}</h4>
                      <button className='profile-button' onClick={() => this.setState({ showAvatarUploadModal: true })}><IntlMessages id={LANG_STRINGS.changePicture} /></button>
                    </div>
                  </div>
                  <div className='personal-detail-attribute-content'>
                    <DetailAttribute imageUrl={PROFILE} label={this.intlText({ id: 'Jenis Kelamin' })} value={_.get(details, 'profile.gender') === 'male' ? <IntlMessages id='Pria' /> : <IntlMessages id='Wanita' />} />
                    <DetailAttribute imageUrl={WEBSITE} label={this.intlText({ id: 'Negara' })} value={getCurrentLocation().country} />
                    <DetailAttribute imageUrl={PHONE} label={this.intlText({ id: 'Nomor Telepon' })} value={_.get(details, 'phone')} />
                    <DetailAttribute
                      imageUrl={CALENDAR}
                      label={this.intlText({ id: 'Tanggal Lahir' })}
                      value={_.get(details, 'profile.dob')
                        ? moment(_.get(details, 'profile.dob')).format('YYYY-MM-DD')
                        : 'N/A'}
                    />
                    <DetailAttribute imageUrl={LOCATION} label={this.intlText({ id: 'Kota' })} value={getCurrentLocation().name} />
                    <DetailAttribute imageUrl={EMAIL} label={this.intlText({ id: 'Email' })} value={_.get(details, 'email')} />
                  </div>
                </div>
              </div>
            </div>
            <div className='profile-detail-card personal-detail-card-gap'>
              <BankAccounts />
            </div>
          </ProfileDetailContainer>
        </ProfileStyleWrapper>
      </React.Fragment>
    )
  }
}

Profile.propTypes = {
  locations: PropTypes.array,
  details: PropTypes.object
}

Profile.defaultProps = {
  locations: [],
  details: {}
}

const WrappedUserProfileForm = Form.create()(injectIntl(Profile))

export default connect(
  state => ({
    details: state.User.details,
    locations: state.User.locations,
    userFile: state.User.userFile,
    userDetailsLoading: state.Loading.GET_USER_DETAILS,
    userDetailsError: state.Error.GET_USER_DETAILS,
    getUserDetailsMessage: state.User.getUserDetailsMessage,
    locationsLoading: state.Loading.GET_LOCATIONS,
    locationsError: state.Error.GET_LOCATIONS,
    getLocationsMessage: state.User.getLocationsMessage,
    uploadFileLoading: state.Loading.UPLOAD_USER_FILE,
    uploadFileError: state.Error.UPLOAD_USER_FILE,
    uploadUserFileMessage: state.User.uploadUserFileMessage,
    updateUserLoading: state.Loading.UPDATE_USER,
    updateUserError: state.Error.UPDATE_USER,
    updateUserMessage: state.User.updateUserMessage,
    updateUserProfileLoading: state.Loading.UPDATE_USER_PROFILE,
    updateUserProfileError: state.Error.UPDATE_USER_PROFILE,
    updateUserProfileMessage: state.User.updateUserProfileMessage,
    updateCompleteUserLoading: state.Loading.UPDATE_COMPLETE_USER,
    updateCompleteUserError: state.Error.UPDATE_COMPLETE_USER,
    updateCompleteUserMessage: state.User.updateCompleteUserMessage,
    bankList: state.MasterData.bankList
  }),
  {
    getUserDetails,
    getLocations,
    uploadUserFile,
    updateUser,
    updateUserProfile,
    updateCompleteUser,
    resetUserRedux
  }
)(WrappedUserProfileForm)
