import React, { Component } from 'react'
import { connect } from 'react-redux'
import BankAccountItemWrapper from './index.style'
import { Checkbox, Icon, Button } from 'antd'
import { injectIntl } from 'react-intl'
import _ from 'lodash/object'
import PropTypes from 'prop-types'
import userActions from '../../../../redux/user/actions'
import IntlMessages from '../../../../components/utility/intlMessages'
import { BANK } from '../../../../constants/icons'
import ProfileModal from '../ProfileModal/profileModal'

const { putUserBankAccounts, deleteUserBankAccounts } = userActions

class BankAccountItem extends Component {
  state = {
    isModalVisible: false
  };

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  };

  getBankName = (bankCode) => {
    const { bankList } = this.props
    const bankDetails = bankList.find(({ id }) => id === Number(bankCode))
    return _.get(bankDetails, 'display_name', '-')
  };

  changeChecked = (e) => {
    const { id } = this.props
    this.props.putUserBankAccounts({
      body: {
        id,
        is_preferred: e.target.checked,
      }
    })
  };

  showModal = () => {
    this.setState({ isModalVisible: true })
  };

  hideModal = () => {
    this.setState({ isModalVisible: false })
  };

  handleDelete = () => {
    const { id } = this.props
    this.props.deleteUserBankAccounts({ body: { id } })
    this.hideModal()
  };

  render () {
    const { isModalVisible } = this.state
    const { holder_name: holderName, bank_code: bankCode, account_no: accountNo, is_preferred: isPreferred } = this.props

    return (
      <BankAccountItemWrapper>
        <div className='bankaccount-item-card'>
          <div className='bankaccount-item-card-content'>
            <div className='bankaccount-item-card-header'>
              <p>
                <Checkbox onChange={this.changeChecked} checked={isPreferred}>
                  <IntlMessages id='Rekening Utama' />
                </Checkbox>
              </p>
              <div className='icon-container' onClick={this.showModal}>
                <Icon type='delete' theme='filled' />
              </div>
            </div>
            <div className='bankaccount-item-card-body'>
              <div className='bankaccount-attribute-icon-container'>
                <img src={BANK} className='bankaccount-attribute-icon' alt='Bank Icon' />
              </div>
              <div className='bankaccount-attribute-text'>
                <p className='bankaccount-attribute-value'>{holderName}</p>
                <div>
                  <p className='bankaccount-attribute-label'>{accountNo}</p>
                  <p className='bankaccount-attribute-label'>{this.getBankName(bankCode)}</p>
                </div>
              </div>
            </div>
          </div>
        </div>
        <ProfileModal isOpen={isModalVisible} onClose={this.hideModal} title={this.intlText({ id: 'Hapus Akun Bank' })}>
          <div className='icon-container-modal'>
            <Icon
              type='delete'
              theme='filled'
              style={{ color: 'red', fontSize: '32px', height: '36px' }}
            />
          </div>
          <div className='confirmation-text'>
            <p>
              Apakah Anda yakin ingin menghapus akun bank <strong>{holderName}</strong> - <strong>{accountNo}</strong> - <strong>{this.getBankName(bankCode)}</strong>?
            </p>
          </div>
          <div className='confirmation-container'>
            <Button type='danger' onClick={this.handleDelete} className='btn-danger'>
              Hapus
            </Button>
            <Button onClick={this.hideModal} className='btn-outline-danger'>
              Batal
            </Button>
          </div>
        </ProfileModal>
      </BankAccountItemWrapper>
    )
  }
}

BankAccountItem.propTypes = {
  id: PropTypes.number.isRequired,
  user: PropTypes.object.isRequired,
  bankList: PropTypes.array.isRequired,
  holder_name: PropTypes.string.isRequired,
  bank_code: PropTypes.string.isRequired,
  account_no: PropTypes.string.isRequired,
  is_preferred: PropTypes.bool.isRequired,
  putUserBankAccounts: PropTypes.func.isRequired,
  deleteUserBankAccounts: PropTypes.func.isRequired
}

export default connect(
  (state) => ({
    updateUserBankAccountsLoading: state.Loading.PUT_USER_BANK_ACCOUNTS,
    deleteUserBankAccountsLoading: state.Loading.DELETE_USER_BANK_ACCOUNTS,
    preferredBankAccountId: state.User.preferredBankAccountId
  }),
  { putUserBankAccounts, deleteUserBankAccounts }
)(injectIntl(BankAccountItem))
