import React, { Component } from 'react'
import { connect } from 'react-redux'
import OtpFormPhoneWrapper from './otpFormPhone.style'
import {
  Form,
  Input,
  Row,
  Col,
  Icon,
  Alert,
  Spin,
  notification
} from 'antd'
import { injectIntl } from 'react-intl'
import userActions from '../../redux/user/actions'
import loadingActions from '../../redux/loading/actions'
import errorActions from '../../redux/error/actions'
import IntlMessages from '../../components/utility/intlMessages'
import PropTypes from 'prop-types'
import { millisecondToHMS } from '../../helpers/utility'


const { sendPhoneOtp, updatePhone, resetUserRedux } = userActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class OtpFormPhone extends Component {
  state = {
    stopwatch: window.sessionStorage.getItem('otpFormEmailCountDown') || 120000
  }

  componentWillMount () {
    // RESET Loading, Error, and operation ID
    this.reset()
  }

  componentWillReceiveProps (nextProps) {
    const {
      sendPhoneOtpLoading,
      sendPhoneOtpError,
      sendPhoneOtpMessage,
      updatePhoneLoading,
      updatePhoneError,
      updatePhoneMessage
    } = nextProps

    if (!sendPhoneOtpLoading && sendPhoneOtpMessage) {
      notification[sendPhoneOtpError ? 'error' : 'success']({
        key: 'phone',
        message: this.intlText({ id: sendPhoneOtpMessage })
      })
      this.props.resetUserRedux(['sendPhoneOtpMessage'])
    }

    if (!updatePhoneLoading && updatePhoneMessage) {
      notification[updatePhoneError ? 'error' : 'success']({
        key: 'phone',
        message: this.intlText({ id: updatePhoneMessage })
      })
      this.props.resetUserRedux(['updatePhoneMessage'])
    }

    if (!updatePhoneLoading && !updatePhoneError && updatePhoneMessage) {
      this.props.updateSuccess('phone')
      this.reset()
    }
  }

  reset () {
    this.props.resetUserRedux(['phoneOperationId', 'updatePhoneCode', 'updatePhoneMessage'])
    this.props.resetErrorRedux(['UPDATE_PHONE', 'SEND_PHONE_OTP'])
    this.props.resetLoadingRedux(['UPDATE_PHONE', 'SEND_PHONE_OTP'])
  }

  handleSubmit = e => {
    e.preventDefault()
    const {
      form,
      phone,
      oldPhone,
      operationId
    } = this.props
    form.validateFields((err, values) => {
      if (!err) {
        const { otp } = values
        this.props.updatePhone({
          body: {
            phone,
            old_phone: oldPhone,
            otp,
            operation_id: operationId
          }
        })
      }
    })
  };

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  sendPhoneOtp = () => {
    const { phone } = this.props
    this.props.sendPhoneOtp({ body: { phone } })
    this.setState({
      stopwatch: 120000
    }, () => {
      this.startTimer()
    })
  }

  startTimer () {
    // If interval exists we clear it
    if (this.decrementer) {
      clearInterval(this.decrementer)
    }
    // Then we decrement stopwatch by 1 every second
    this.decrementer = setInterval(() => {
      let countDown = this.state.stopwatch - 1000
      window.sessionStorage.setItem('otpFormPhoneCountDown', countDown)
      this.setState({ stopwatch: countDown })
    }, 1000)
  }

  msToHMS = ms => {
    return millisecondToHMS(ms)
  }

  render () {
    const {
      form,
      sendPhoneOtpLoading,
      updatePhoneLoading,
      updatePhoneError,
      updatePhoneMessage,
      operationId
    } = this.props
    const {
      stopwatch
    } = this.state
    const { getFieldDecorator } = form
    return (
      <OtpFormPhoneWrapper>
        <Row>
            <div className='otp-card'>
              <div className='otp-card-content'>
                <Spin spinning={!!sendPhoneOtpLoading || !!updatePhoneLoading}>
                  <h3><IntlMessages id='Verifikasi No Telepon' /></h3>
                  {updatePhoneError && updatePhoneMessage && (
                    <Alert message={updatePhoneMessage} type='error' />
                  )}
                  {
                    !operationId ? (
                      <div>
                        <p>
                          <IntlMessages id='Harap validasi no telepon' />
                        </p>
                        <a className='bold-link-blue' onClick={() => this.sendPhoneOtp()}>
                          <IntlMessages id='Kirim OTP' />
                        </a>
                      </div>
                    ) : (
                      <Form layout='inline'>
                        <p>
                          <IntlMessages id='Harap masukkan OTP' />
                        </p>
                        <Form.Item style={{ width: '100%' }}>
                          {getFieldDecorator('otp', {
                            rules: [{
                              required: true,
                              message: this.intlText({ id: 'Harap masukkan OTP' })
                            }, {
                              len: 6,
                              message: this.intlText({ id: 'OTP harus 6 digit' })
                            }]
                          })(
                            <Input
                              placeholder='OTP'
                            />
                          )}
                        </Form.Item>
                        <Form.Item>
                          <a className='bold-link-blue' onClick={this.handleSubmit}>
                            <IntlMessages id='Verifikasi OTP' />
                          </a>
                        </Form.Item>
                        <Form.Item>
                          <a
                            className='bold-link-blue'
                            onClick={() => this.sendPhoneOtp()}
                            disabled={stopwatch > 0}
                          >
                            {stopwatch > 0
                              ? this.msToHMS(stopwatch)
                              : <IntlMessages id='Kirim Ulang OTP' />}
                          </a>
                        </Form.Item>
                      </Form>
                    )
                  }
                </Spin>
              </div>
            </div>
        </Row>
        <Row>
          <div className='otp-phone-info'>
            <span>
              <Icon type='exclamation-circle' /> <IntlMessages id='Harap dicatat bahwa Anda akan keluar setelah verifikasi nomor telepon. Silakan gunakan nomor baru untuk login lagi' />
            </span>
          </div>
        </Row>
      </OtpFormPhoneWrapper>
    )
  }
}

OtpFormPhone.propTypes = {
  phone: PropTypes.string
}

OtpFormPhone.defaultProps = {
  phone: ''
}

const WrappedOtpFormPhone = Form.create()(injectIntl(OtpFormPhone))

export default connect(
  state => ({
    operationId: state.User.phoneOperationId,
    sendPhoneOtpLoading: state.Loading.SEND_PHONE_OTP,
    sendPhoneOtpError: state.Error.SEND_PHONE_OTP,
    sendPhoneOtpMessage: state.Error.sendPhoneOtpMessage,
    updatePhoneLoading: state.Loading.UPDATE_PHONE,
    updatePhoneError: state.Error.UPDATE_PHONE,
    updatePhoneMessage: state.User.updatePhoneMessage,
    updatePhoneCode: state.User.updatePhoneCode
  }),
  {
    sendPhoneOtp,
    resetUserRedux,
    updatePhone,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedOtpFormPhone)
