import React, { Component } from 'react'
import { connect } from 'react-redux'
import NewBankAccountFormWrapper, { BankComponentStyle } from './newBankAcccountForm.style'
import {
  Form,
  Input,
  Checkbox,
  Button,
  Select,
  Spin,
  notification
} from 'antd'
import { injectIntl } from 'react-intl'
import _ from 'lodash/object'
import PropTypes from 'prop-types'
import userActions from '../../redux/user/actions'
import IntlMessages from '../../components/utility/intlMessages'
import { CLAIM_LANG } from '../Claim/constants'
import { get } from 'lodash'
import ProfileModal from './components/ProfileModal/profileModal'

const Option = Select.Option

const {
  postUserBankAccounts,
  resetUserRedux,
  verifyBankAccount
} = userActions

class NewBankAccountForm extends Component {
  state = {
    showAccountHolderName: false
  }

  componentDidMount () {
    this.props.resetUserRedux(['verifyBankAccountStatus'])
  }

  componentWillReceiveProps (nextProps) {
    const {
      verifyBankAccountStatus,
      verifyBankAccountLoading,
      verifyBankAccountError
    } = nextProps

    if (!verifyBankAccountLoading && verifyBankAccountStatus) {
      notification[verifyBankAccountError ? 'error' : 'success']({
        message: this.intlText({ id: verifyBankAccountError ? 'Error' : 'Rekening bank valid' }),
        description: verifyBankAccountError ? this.intlText({ id: verifyBankAccountStatus }) : ''
      })
      if (verifyBankAccountError === false) {
        this.setState({ showAccountHolderName: true })
      }
      this.setState({
        loaderForm: {}
      })
      this.props.resetUserRedux(['verifyBankAccountStatus'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  handleSubmit = e => {
    e.preventDefault()
    const { user } = this.props
    this.props.form.validateFields((err, {
      account_no: accountNo,
      bank_code: bankCode,
      branch_name: branchName,
      holder_name: holderName,
      is_preferred: isPreferred
    }) => {
      if (!err) {
        const { verifyAccountData = {} } = this.props
        const { showAccountHolderName } = this.state
        const { account_holder_name: accountHolderName } = verifyAccountData
        if (showAccountHolderName || this.checkVietBank()) {
          this.props.postUserBankAccounts({
            body: {
              account_no: accountNo,
              bank_code: String(bankCode),
              branch_name: branchName,
              holder_name: accountHolderName,
              is_preferred: isPreferred
            }
          })
          this.setState({ showAccountHolderName: false })
        } else {
          this.props.verifyBankAccount({
            body: {
              user,
              account_no: accountNo,
              bank_code: String(bankCode),
              branch_name: branchName,
              holder_name: holderName,
              is_preferred: isPreferred
            }
          })
        }
      }
    })
  }

  checkVietBank = () => {
    const { userDetails } = this.props
    const userPhone = get(userDetails, 'phone', '')
    let vietBankPattern = /^(\+84|84)/
    return vietBankPattern.test(userPhone)
  }

  handleFieldValueChange = () => {
    this.setState({ showAccountHolderName: false })
  }

  renderAccountHolderName = () => {
    const { verifyAccountData = {} } = this.props
    const { showAccountHolderName } = this.state
    const { account_holder_name: accountHolderName } = verifyAccountData

    return showAccountHolderName &&
      <BankComponentStyle>
        <div className='heading'>Account Holder's name</div>
        <div className='value'>{accountHolderName}</div>
      </BankComponentStyle>
  }

  render () {
    const {
      form,
      bankList,
      postUserBankAccountsLoading,
      verifyBankAccountLoading,
      showBankForm
    } = this.props
    const { showAccountHolderName } = this.state
    const { getFieldDecorator } = form
    return (
      <ProfileModal isOpen={showBankForm} title={this.intlText({ id: 'Rincian Rekening Baru' })}>
        <NewBankAccountFormWrapper>
          <div className='bank-account-form-container'>
            <Spin spinning={!!postUserBankAccountsLoading || !!verifyBankAccountLoading}>
              <Form
                onSubmit={this.handleSubmit}
                className='bank-account-form'
              >
                <Form.Item label={this.intlText({ id: 'Nama Bank' })}>
                  {getFieldDecorator('bank_code', {
                    rules: [
                      {
                        required: true,
                        message: this.intlText({ id: 'Nama Bank Harus Diisi' })
                      }
                    ]
                  })(
                    <Select
                      showSearch
                      placeholder={this.intlText({ id: 'Pilih Bank' })}
                      onChange={this.handleFieldValueChange}
                      filterOption={(input, option) =>
                        _.get(option, 'props.children', '').toLowerCase().includes(input.toLowerCase())}
                    >
                      {
                        bankList.map(({ id, display_name: displayName }) => {
                          return (
                            <Option
                              key={id}
                              value={id}
                            >
                              {displayName}
                            </Option>
                          )
                        })
                      }
                    </Select>
                  )}
                </Form.Item>
                <Form.Item label={this.intlText({ id: 'Nomor Rekening' })}>
                  {getFieldDecorator('account_no', {
                    rules: [
                      {
                        required: true,
                        message: this.intlText({ id: 'Nomor Rekening Harus Diisi' })
                      },
                      {
                        pattern: /^[a-z0-9]+$/i,
                        message: this.intlText({ id: 'Nomor Rekening Hanya Boleh Huruf Dan Angka' })
                      }
                    ]
                  })(
                    <Input
                      placeholder={this.intlText({ id: 'Nomor Rekening' })}
                      onChange={this.handleFieldValueChange}
                    />
                  )}
                </Form.Item>
                {
                  this.renderAccountHolderName()
                }
                <Form.Item>
                  {getFieldDecorator('is_preferred', {
                    valuePropName: 'checked'
                  })(
                    <Checkbox>
                      <IntlMessages id='Rekening Utama' />
                    </Checkbox>
                  )}
                </Form.Item>
                <div className='confirmation-container'>
                  <Button
                    type='primary'
                    htmlType='submit'
                    disabled={!!postUserBankAccountsLoading}
                    className='btn-success'
                  >
                    <IntlMessages id={showAccountHolderName || this.checkVietBank() ? CLAIM_LANG.saveDetails : CLAIM_LANG.findMyAccount} />
                  </Button>
                  <Button
                    type='primary'
                    htmlType='reset'
                    disabled={!!postUserBankAccountsLoading}
                    className='btn-outline-success'
                    onClick={this.props.onClose}
                  >
                    <IntlMessages id={this.intlText({ id: 'Batal' })} />
                  </Button>
                </div>
              </Form>
            </Spin>
          </div>
        </NewBankAccountFormWrapper>
      </ProfileModal>
    )
  }
}

NewBankAccountForm.propTypes = {
  locations: PropTypes.array.isRequired,
  bankList: PropTypes.array.isRequired,
  showBankForm: PropTypes.bool.isRequired,
  onClose: PropTypes.func.isRequired
}

NewBankAccountForm.defaultProps = {
  locations: [],
  bankList: [],
  showBankForm: false
}

const WrappedUserNewBankAccountForm = Form.create()(injectIntl(NewBankAccountForm))

export default connect(
  state => ({
    userDetails: state.User.details,

    postUserBankAccountsLoading: state.Loading.POST_USER_BANK_ACCOUNTS,
    verifyBankAccountLoading: state.Loading.VERIFY_BANK_ACCOUNT,
    verifyBankAccountError: state.Error.VERIFY_BANK_ACCOUNT,
    verifyBankAccountStatus: state.User.verifyBankAccountStatus,
    verifyAccountData: state.User.verifyAccountData
  }),
  {
    postUserBankAccounts,
    resetUserRedux,
    verifyBankAccount
  }
)(WrappedUserNewBankAccountForm)
