import React, { Component } from 'react'
import { connect } from 'react-redux'
import OtpFormEmailWrapper from './otpFormEmail.style'
import {
  Form,
  Input,
  Alert,
  Spin,
  notification
} from 'antd'
import { injectIntl } from 'react-intl'
import userActions from '../../redux/user/actions'
import loadingActions from '../../redux/loading/actions'
import errorActions from '../../redux/error/actions'
import IntlMessages from '../../components/utility/intlMessages'
import PropTypes from 'prop-types'
import { millisecondToHMS } from '../../helpers/utility'


const { sendEmailOtp, updateEmail, resetUserRedux, addEmail } = userActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class OtpFormEmail extends Component {
  state = {
    stopwatch: window.sessionStorage.getItem('otpFormEmailCountDown') || 120000
  }

  componentWillMount () {
    // RESET Loading, Error, and operation ID
    this.reset()
  }

  componentWillReceiveProps (nextProps) {
    const {
      sendEmailOtpLoading,
      sendEmailOtpError,
      sendEmailOtpMessage,
      updateEmailLoading,
      updateEmailError,
      updateEmailMessage,
      addEmailLoading,
      addEmailError,
      addEmailMessage
    } = nextProps

    if (!sendEmailOtpLoading && sendEmailOtpMessage) {
      notification[sendEmailOtpError ? 'error' : 'success']({
        key: 'email',
        message: this.intlText({ id: sendEmailOtpMessage })
      })
      this.props.resetUserRedux(['sendEmailOtpMessage'])
    }

    if (!updateEmailLoading && updateEmailMessage) {
      notification[updateEmailError ? 'error' : 'success']({
        key: 'email',
        message: this.intlText({ id: updateEmailMessage })
      })
      this.props.resetUserRedux(['updateEmailMessage'])
    }

    if (!addEmailLoading && addEmailMessage) {
      notification[addEmailError ? 'error' : 'success']({
        key: 'email',
        message: this.intlText({ id: addEmailMessage })
      })
      this.props.resetUserRedux(['addEmailMessage'])
    }

    if ((!updateEmailLoading && !updateEmailError && updateEmailMessage) || (!addEmailLoading && !addEmailError && addEmailMessage)) {
      this.props.updateSuccess('email')
      this.reset()
    }
  }

  reset () {
    this.props.resetUserRedux(['emailOperationId', 'updateEmailCode', 'updateEmailMessage', 'addEmailCode', 'addEmailMessage'])
    this.props.resetErrorRedux(['UPDATE_EMAIL', 'SEND_EMAIL_OTP', 'ADD_EMAIL'])
    this.props.resetLoadingRedux(['UPDATE_EMAIL', 'SEND_EMAIL_OTP', 'ADD_EMAIL'])
  }

  handleSubmit = e => {
    e.preventDefault()
    const {
      form,
      email,
      oldEmail,
      operationId
    } = this.props
    form.validateFields((err, values) => {
      if (!err) {
        const { otp } = values
        if (oldEmail) {
          this.props.updateEmail({
            body: {
              email,
              old_email: oldEmail,
              otp,
              operation_id: operationId
            }
          })
        } else {
          this.props.addEmail({
            body: {
              email,
              otp,
              operation_id: operationId
            }
          })
        }
      }
    })
  };

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  sendEmailOtp = () => {
    const { email } = this.props
    this.props.sendEmailOtp({ body: { email, type: 'email' } })
    this.setState({
      stopwatch: 120000
    }, () => {
      this.startTimer()
    })
  }

  startTimer () {
    // If interval exists we clear it
    if (this.decrementer) {
      clearInterval(this.decrementer)
    }
    // Then we decrement stopwatch by 1 every second
    this.decrementer = setInterval(() => {
      let countDown = this.state.stopwatch - 1000
      window.sessionStorage.setItem('otpFormEmailCountDown', countDown)
      this.setState({ stopwatch: countDown })
    }, 1000)
  }

  msToHMS = ms => {
    return millisecondToHMS(ms)
  }

  render () {
    const {
      form,
      sendEmailOtpLoading,
      updateEmailLoading,
      updateEmailError,
      updateEmailMessage,
      operationId
    } = this.props
    const {
      stopwatch
    } = this.state
    const { getFieldDecorator } = form
    return (
      <OtpFormEmailWrapper>
        <div className='otp-card'>
          <div className='otp-card-content'>
            <Spin spinning={!!sendEmailOtpLoading || !!updateEmailLoading}>
              <h3><IntlMessages id='Verifikasi Email' /></h3>
              {updateEmailError && updateEmailMessage && (
                <Alert message={updateEmailMessage} type='error' />
              )}
              {
                !operationId ? (
                  <div>
                    <p>
                      <IntlMessages id='Harap validasi Email' />
                    </p>
                    <a className='bold-link-blue' onClick={() => this.sendEmailOtp()}>
                      <IntlMessages id='Kirim OTP' />
                    </a>
                  </div>
                ) : (
                  <Form layout='inline'>
                    <p>
                      <IntlMessages id='Harap masukkan OTP' />
                    </p>
                    <Form.Item style={{ width: '100%' }}>
                      {getFieldDecorator('otp', {
                        rules: [{
                          required: true,
                          message: this.intlText({ id: 'Harap masukkan OTP' })
                        }, {
                          len: 6,
                          message: this.intlText({ id: 'OTP harus 6 digit' })
                        }]
                      })(
                        <Input
                          placeholder='OTP'
                        />
                      )}
                    </Form.Item>
                    <Form.Item>
                      <a className='bold-link-blue' onClick={this.handleSubmit}>
                        <IntlMessages id='Verifikasi OTP' />
                      </a>
                    </Form.Item>
                    <Form.Item>
                      <a
                        className='bold-link-blue'
                        onClick={() => this.sendEmailOtp()}
                        disabled={stopwatch > 0}
                      >
                        {stopwatch > 0
                          ? this.msToHMS(stopwatch)
                          : <IntlMessages id='Kirim Ulang OTP' />}
                      </a>
                    </Form.Item>
                  </Form>
                )
              }
            </Spin>
          </div>
        </div>
      </OtpFormEmailWrapper>
    )
  }
}

OtpFormEmail.propTypes = {
  email: PropTypes.string
}

OtpFormEmail.defaultProps = {
  email: []
}

const WrappedOtpFormEmail = Form.create()(injectIntl(OtpFormEmail))

export default connect(
  state => ({
    operationId: state.User.emailOperationId,
    sendEmailOtpLoading: state.Loading.SEND_EMAIL_OTP,
    sendEmailOtpError: state.Error.SEND_EMAIL_OTP,
    sendEmailOtpMessage: state.User.sendEmailOtpMessage,
    updateEmailLoading: state.Loading.UPDATE_EMAIL,
    updateEmailError: state.Error.UPDATE_EMAIL,
    addEmailLoading: state.Loading.ADD_EMAIL,
    addEmailError: state.Error.ADD_EMAIL,
    updateEmailMessage: state.User.updateEmailMessage,
    updateEmailCode: state.User.updateEmailCode,
    addEmailMessage: state.User.addEmailMessage,
    addEmailCode: state.User.addEmailCode
  }),
  {
    sendEmailOtp,
    resetUserRedux,
    updateEmail,
    addEmail,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedOtpFormEmail)
