import React, { Component } from 'react'
import { connect } from 'react-redux'
import BankAccountsWrapper from './index.style'
import {
  Row,
  Alert,
  notification,
  Col
} from 'antd'
import { injectIntl } from 'react-intl'
import _ from 'lodash/object'
import PropTypes from 'prop-types'
import userActions from '../../../../redux/user/actions'
import masterDataActions from '../../../../redux/masterData/actions'
import IntlMessages from '../../../../components/utility/intlMessages'
import BankAccountItem from '../BankAccountItem'
import NewBankAccountForm from '../../newBankAccountForm'
import CircularLoader from '../../../../components/CircularLoader'

const {
  getUserBankAccounts,
  resetUserRedux
} = userActions

const {
  getBankList
} = masterDataActions

class BankAccounts extends Component {
  state = {
    showNewBankAccountForm: false
  }

  componentDidMount () {
    this.props.getUserBankAccounts()
    this.props.getBankList()
  }

  componentWillReceiveProps (nextProps) {
    const {
      getUserBankAccountsLoading,
      getUserBankAccountsError,
      getUserBankAccountsMessage,

      getBankListLoading,
      getBankListError,
      getBankListMessage,

      userDetailsLoading,
      userDetailsError,
      getUserDetailsMessage,

      updateUserBankAccountsLoading,
      updateUserBankAccountsError,
      updateUserBankAccountsMessage,

      deleteUserBankAccountsLoading,
      deleteUserBankAccountsError,
      deleteUserBankAccountsMessage,

      postUserBankAccountsLoading,
      postUserBankAccountsError,
      postUserBankAccountsMessage,

      verifyBankAccountError
    } = nextProps

    if (!getUserBankAccountsLoading && !!getUserBankAccountsError && getUserBankAccountsMessage) {
      notification.error({
        message: this.intlText({ id: getUserBankAccountsMessage })
      })
      this.props.resetUserRedux(['getUserBankAccountsMessage'])
    }

    if (!getBankListLoading && !!getBankListError && getBankListMessage) {
      notification.error({
        message: this.intlText({ id: getBankListMessage })
      })
      this.props.resetUserRedux(['getBankListMessage'])
    }

    if (!userDetailsLoading && !!userDetailsError && getUserDetailsMessage) {
      notification.error({
        message: this.intlText({ id: getUserDetailsMessage })
      })
      this.props.resetUserRedux(['getUserDetailsMessage'])
    }

    if (!updateUserBankAccountsLoading && updateUserBankAccountsMessage) {
      notification[updateUserBankAccountsError ? 'error' : 'success']({
        message: this.intlText({ id: updateUserBankAccountsMessage })
      })
      this.props.resetUserRedux(['updateUserBankAccountsMessage'])
    }

    if (!deleteUserBankAccountsLoading && deleteUserBankAccountsMessage) {
      notification[deleteUserBankAccountsError ? 'error' : 'success']({
        message: this.intlText({ id: deleteUserBankAccountsMessage })
      })
      this.props.resetUserRedux(['deleteUserBankAccountsMessage'])
    }

    if (!postUserBankAccountsLoading && postUserBankAccountsMessage && !verifyBankAccountError) {
      // if post user bank account error, not validate bank error
      notification[postUserBankAccountsError ? 'error' : 'success']({
        message: this.intlText({ id: postUserBankAccountsMessage })
      })
      if (!postUserBankAccountsError) {
        this.setState({
          showNewBankAccountForm: false
        })
      }
      this.props.resetUserRedux(['postUserBankAccountsMessage'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  toggleBankAccountForm = () => {
    // show form or not
    const { showNewBankAccountForm } = this.state
    this.setState({
      showNewBankAccountForm: !showNewBankAccountForm
    })
  }

  render () {
    const {
      showNewBankAccountForm
    } = this.state
    const {
      bankList,
      userDetails,
      userDetailsLoading,
      userDetailsError,
      getUserDetailsMessage,
      userBankAccounts,
      getUserBankAccountsLoading,
      getUserBankAccountsError,
      getUserBankAccountsMessage,
      getBankListLoading,
      getBankListError,
      getBankListMessage,
      deleteUserBankAccountsLoading,
      updateUserBankAccountsLoading
    } = this.props
    return (
      <BankAccountsWrapper>
        <div className='bank-accounts-container'>
          <CircularLoader isSpining={!!getUserBankAccountsLoading || !!deleteUserBankAccountsLoading || !!updateUserBankAccountsLoading} size='24px'>
            <div className='content-header-text'>
              <h3><IntlMessages id='Informasi Bank' /></h3>
              {
                !(!getBankListLoading && !!getBankListError && getBankListMessage) && <button
                  type={showNewBankAccountForm ? 'danger' : 'primary'}
                  className='bank-account-new-btn'
                  onClick={() => this.toggleBankAccountForm()}
                  disabled={!!userDetailsError}
                >
                  {
                    showNewBankAccountForm ? (
                      <div>
                        <IntlMessages id='Batalkan' />
                      </div>
                    ) : (
                      <div>
                        <IntlMessages id='Tambah Rekening' />
                      </div>
                    )
                  }
                </button>
              }
            </div>
            {!getUserBankAccountsLoading && !!getUserBankAccountsError && getUserBankAccountsMessage && (
              <Alert type='error' description={getUserBankAccountsMessage} />
            )}
            {!getBankListLoading && !!getBankListError && getBankListMessage && (
              <Alert type='error' description={getBankListMessage} />
            )}
            {!!(!getUserBankAccountsError && !getBankListError && userBankAccounts.length) &&
              <Row type='flex' className='bank-items-container' gutter={[{ xs: 8, sm: 10, md: 24, lg: 32 }, 20]}>
                {
                  userBankAccounts.map((userBankAccount, index) => (
                    <Col lg={8} xl={8} md={8} sm={8} xs={24} className='gutter-row' key={index}>
                      <BankAccountItem
                        index={index}
                        bankList={bankList}
                        {...userBankAccount}
                      />
                    </Col>
                  ))
                }
              </Row>
            }
          </CircularLoader>
          <div className='new-bank-account-container'>
            {!userDetailsLoading && !!userDetailsError && getUserDetailsMessage && (
              <Alert type='error' description={this.intlText({ id: getUserDetailsMessage })} />
            )}
            <NewBankAccountForm
              bankList={bankList}
              user={_.get(userDetails, 'id')}
              showBankForm={this.state.showNewBankAccountForm}
              onClose={() => this.setState({ showNewBankAccountForm: false })}
            />
          </div>
        </div>
      </BankAccountsWrapper>
    )
  }
}

BankAccounts.propTypes = {
  userBankAccounts: PropTypes.array
}

BankAccounts.defaultProps = {
  userBankAccounts: []
}

export default connect(
  state => ({
    userDetails: state.User.details,
    bankList: state.MasterData.bankList,
    userBankAccounts: state.User.userBankAccounts,
    getUserBankAccountsLoading: state.Loading.GET_USER_BANK_ACCOUNTS,
    getUserBankAccountsError: state.Error.GET_USER_BANK_ACCOUNTS,
    getUserBankAccountsMessage: state.User.getUserBankAccountsMessage,
    getBankListLoading: state.Loading.GET_BANK_LIST,
    getBankListError: state.Error.GET_BANK_LIST,
    getBankListMessage: state.MasterData.getBankListMessage,
    userDetailsLoading: state.Loading.GET_USER_DETAILS,
    userDetailsError: state.Loading.GET_USER_DETAILS,
    getUserDetailsMessage: state.User.getUserDetailsMessage,
    updateUserBankAccountsLoading: state.Loading.PUT_USER_BANK_ACCOUNTS,
    updateUserBankAccountsError: state.Error.PUT_USER_BANK_ACCOUNTS,
    updateUserBankAccountsMessage: state.User.updateUserBankAccountsMessage,
    deleteUserBankAccountsLoading: state.Loading.DELETE_USER_BANK_ACCOUNTS,
    deleteUserBankAccountsError: state.Error.DELETE_USER_BANK_ACCOUNTS,
    deleteUserBankAccountsMessage: state.User.deleteUserBankAccountsMessage,
    postUserBankAccountsLoading: state.Loading.POST_USER_BANK_ACCOUNTS,
    postUserBankAccountsError: state.Error.POST_USER_BANK_ACCOUNTS,
    postUserBankAccountsMessage: state.User.postUserBankAccountsMessage,
    verifyBankAccountError: state.Error.VERIFY_BANK_ACCOUNT
  }),
  {
    getUserBankAccounts,
    getBankList,
    resetUserRedux
  }
)(injectIntl(BankAccounts))
